export const SOUND_IDS=['bell','zombie-aggro','zombie-death','level-up','dragon-wings','enemy-growl','enemy-undead','enemy-beast','enemy-death','enemy-cast','enemy-hurt','enemy-human','lightning','sword','fireball','bow','volley','ice','witch-laugh','witch-pool','witch-kill','troll-aggro','villager-1','villager-2','villager-3','villager-woman','ambient-raven','ambient-wolf','wolf-attack','skeleton-death','wounded','troll-voice','lich-summon','ghost-spawn','ghost-combat','werewolf-aggro','werewolf-hit','dragon-flight','bear-hit'];
// Separate media voices let the witch's victory line finish while Web Audio is suspended.
export function soundEffects({muted=()=>false,makeAudio=url=>new Audio(url),onActivity=()=>{}}={}){
 const templates=new Map(SOUND_IDS.map(id=>{const a=makeAudio(new URL('./assets/sfx-'+id+'.mp3',import.meta.url).href);a.preload='none';return [id,a]})),voices=new Set();let trollVoice=false,mixVolume=1;
 function stop(includeVictory=false){for(const v of [...voices])if(includeVictory||v.id!=='witch-kill'){v.audio.pause();v.clean?.(false)}}
 function play(id,{volume=1,onEnded}={}){if(id==='bell-stop'){for(const v of [...voices])if(v.id==='bell'){v.audio.pause();v.clean?.(false)}return}if(id==='troll-aggro'){id=trollVoice?'troll-voice':'troll-aggro';trollVoice=!trollVoice}if(muted()||!templates.has(id))return;if(id==='wounded'&&[...voices].some(v=>v.id===id))return;if(id.startsWith('troll-'))for(const v of [...voices])if(v.id.startsWith('troll-')){v.audio.pause();v.clean?.(false)}if(id.startsWith('villager-'))for(const v of [...voices])if(v.id.startsWith('villager-')){v.audio.pause();v.clean?.(false)}const voiceOnly=['witch-laugh','witch-pool','witch-kill'].includes(id);if(voiceOnly)for(const v of [...voices])if(v.id.startsWith('witch-')){v.audio.pause();v.clean?.(false)}
 const matching=[...voices].filter(v=>v.id===id);if(matching.length>=4){matching[0].audio.pause();matching[0].clean?.(false)}
 while(voices.size>=14){const oldest=[...voices].find(v=>v.id!=='witch-kill');if(!oldest)break;oldest.audio.pause();oldest.clean?.(false)}const audio=templates.get(id).cloneNode(),v={id,audio};audio.volume=id==='dragon-flight'?.24:id==='dragon-wings'?.3:id.startsWith('enemy-')?.45:id.startsWith('ambient-')?.13:id.startsWith('villager-')?.65:id==='wolf-attack'?.5:id.startsWith('witch-')?.9:.75;audio.volume*=Math.max(0,Math.min(1,Number.isFinite(volume)?volume:1));v.baseVolume=audio.volume;audio.volume=v.baseVolume*mixVolume;audio.muted=muted();voices.add(v);onActivity(id,v,true);const clean=(ended=false)=>{if(voices.delete(v)){onActivity(id,v,false);if(ended)optionsOnEnded?.()}};const optionsOnEnded=onEnded;v.clean=clean;audio.onended=()=>clean(true);audio.onerror=()=>clean(false);try{const result=audio.play();result?.catch(()=>clean(false))}catch{clean()}}
 return {get volume(){return mixVolume},set volume(value){if(!Number.isFinite(value))return;mixVolume=Math.max(0,Math.min(1,value));for(const v of voices)v.audio.volume=v.baseVolume*mixVolume},play,stop,syncMute(){for(const v of voices)v.audio.muted=muted()}};
}
